"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[37688],{3331:(a,e,i)=>{i.d(e,{R:()=>t,x:()=>s});var l=i(36672);const n={},r=l.createContext(n);function t(a){const e=l.useContext(r);return l.useMemo((function(){return"function"==typeof a?a(e):{...e,...a}}),[e,a])}function s(a){let e;return e=a.disableParentContext?"function"==typeof a.components?a.components(n):a.components||n:t(a.components),l.createElement(r.Provider,{value:e},a.children)}},23074:(a,e,i)=>{i.r(e),i.d(e,{assets:()=>d,contentTitle:()=>s,default:()=>k,frontMatter:()=>t,metadata:()=>l,toc:()=>m});const l=JSON.parse('{"id":"2023/04/16","title":"2023-04-16","description":"Valve, Olumsuz Bir Oyun \u0130ncelemesini Faydal\u0131 Olarak \u0130\u015faretleyen 2500 Kullan\u0131c\u0131n\u0131n Hesab\u0131n\u0131 K\u0131s\u0131tlad\u0131","source":"@site/i18n/tr/docusaurus-plugin-content-docs/current/2023/04/16.md","sourceDirName":"2023/04","slug":"/2023/04/16","permalink":"/tr/2023/04/16","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/tr/docusaurus-plugin-content-docs//current/2023/04/16.md","tags":[],"version":"current","frontMatter":{"localized_date":"16 Nisan 2023","top_news":"Valve, Olumsuz Bir Oyun \u0130ncelemesini Faydal\u0131 Olarak \u0130\u015faretleyen 2500 Kullan\u0131c\u0131n\u0131n Hesab\u0131n\u0131 K\u0131s\u0131tlad\u0131"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-17","permalink":"/tr/2023/04/17"},"next":{"title":"2023-04-15","permalink":"/tr/2023/04/15"}}');var n=i(23420),r=i(3331);const t={localized_date:"16 Nisan 2023",top_news:"Valve, Olumsuz Bir Oyun \u0130ncelemesini Faydal\u0131 Olarak \u0130\u015faretleyen 2500 Kullan\u0131c\u0131n\u0131n Hesab\u0131n\u0131 K\u0131s\u0131tlad\u0131"},s="2023-04-16",d={},m=[{value:"Valve, Olumsuz Bir Oyun \u0130ncelemesini Faydal\u0131 Olarak \u0130\u015faretleyen 2500 Kullan\u0131c\u0131n\u0131n Hesab\u0131n\u0131 K\u0131s\u0131tlad\u0131",id:"valve-olumsuz-bir-oyun-i\u0307ncelemesini-faydal\u0131-olarak-i\u0307\u015faretleyen-2500-kullan\u0131c\u0131n\u0131n-hesab\u0131n\u0131-k\u0131s\u0131tlad\u0131",level:2},{value:"Plastik ambalajl\u0131 bir hindili sandvi\xe7 neden New York havaalan\u0131nda 15 dolar?",id:"plastik-ambalajl\u0131-bir-hindili-sandvi\xe7-neden-new-york-havaalan\u0131nda-15-dolar",level:2},{value:"Lofi hava trafik kontrol\xfc - LAX",id:"lofi-hava-trafik-kontrol\xfc---lax",level:2},{value:"Transformat\xf6r modelleri nelerdir ve nas\u0131l \xe7al\u0131\u015f\u0131rlar?",id:"transformat\xf6r-modelleri-nelerdir-ve-nas\u0131l-\xe7al\u0131\u015f\u0131rlar",level:2},{value:"WebGPU Temelleri",id:"webgpu-temelleri",level:2},{value:"Google CEO&#39;su: &quot;bu grubun ayar\u0131n\u0131 ge\xe7mi\u015f kapal\u0131 olarak de\u011fi\u015ftirebilir miyiz&quot; [pdf]",id:"google-ceosu-bu-grubun-ayar\u0131n\u0131-ge\xe7mi\u015f-kapal\u0131-olarak-de\u011fi\u015ftirebilir-miyiz-pdf",level:2},{value:"Surviving Burnout (2015)",id:"surviving-burnout-2015",level:2},{value:"D\xfc\u015f\xfck Kodlu Yaz\u0131l\u0131m Geli\u015ftirme Bir Yaland\u0131r",id:"d\xfc\u015f\xfck-kodlu-yaz\u0131l\u0131m-geli\u015ftirme-bir-yaland\u0131r",level:2},{value:"Google&#39;da d\xfczeltmek istemedikleri uzaktan kod \xe7al\u0131\u015ft\u0131rma g\xfcvenlik a\xe7\u0131\u011f\u0131",id:"googleda-d\xfczeltmek-istemedikleri-uzaktan-kod-\xe7al\u0131\u015ft\u0131rma-g\xfcvenlik-a\xe7\u0131\u011f\u0131",level:2},{value:"Rust&#39;ta Hiperviz\xf6r Geli\u015ftirme",id:"rustta-hiperviz\xf6r-geli\u015ftirme",level:2}];function o(a){const e={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...a.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(e.header,{children:(0,n.jsx)(e.h1,{id:"2023-04-16",children:"2023-04-16"})}),"\n",(0,n.jsx)(e.h2,{id:"valve-olumsuz-bir-oyun-i\u0307ncelemesini-faydal\u0131-olarak-i\u0307\u015faretleyen-2500-kullan\u0131c\u0131n\u0131n-hesab\u0131n\u0131-k\u0131s\u0131tlad\u0131",children:"Valve, Olumsuz Bir Oyun \u0130ncelemesini Faydal\u0131 Olarak \u0130\u015faretleyen 2500 Kullan\u0131c\u0131n\u0131n Hesab\u0131n\u0131 K\u0131s\u0131tlad\u0131"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://tech.slashdot.org/story/23/04/14/175246/valve-restricts-accounts-of-2500-users-who-marked-a-negative-game-review-useful",children:"Orijinal"}),'.\nValve, Warlander i\xe7in olumsuz bir inceleme i\u015faretleyen 2500 kullan\u0131c\u0131n\u0131n hesaplar\u0131n\u0131 k\u0131s\u0131tlad\u0131 ve etkilenenler i\xe7in 30 g\xfcnl\xfck yukar\u0131 ve a\u015fa\u011f\u0131 oylama yasa\u011f\u0131na yol a\xe7t\u0131. Steam moderat\xf6rleri incelemeyi "kullan\u0131c\u0131lar\u0131 doland\u0131rmaya \xe7al\u0131\u015fmak veya Steam Kural ve Y\xf6nergelerinin di\u011fer ihlalleri" olarak s\u0131n\u0131fland\u0131rarak incelemenin kald\u0131r\u0131lmas\u0131na neden oldu ve bir\xe7ok ki\u015fi Valve\'\u0131n eylemlerinin etkisi nedeniyle inceleme sisteminin "tamamen anlams\u0131z" oldu\u011funa inan\u0131yor.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35577895",children:"Discussion Service"}),".\nValve'\u0131n olumsuz bir oyun incelemesini faydal\u0131 olarak i\u015faretleyen kullan\u0131c\u0131lar\u0131n hesaplar\u0131n\u0131 k\u0131s\u0131tlamas\u0131, Hacker News kullan\u0131c\u0131lar\u0131n\u0131n Valve'\u0131n platformlar\u0131nda \"k\xf6t\xfc niyetli yaz\u0131l\u0131mlara\" izin vermesini ele\u015ftirmesine yol a\xe7t\u0131. Baz\u0131lar\u0131 hile kar\u015f\u0131t\u0131 yaz\u0131l\u0131ma alternatifler \xf6nerirken, di\u011ferleri bunun \xe7evrimi\xe7i oyunlarda hileyi \xf6nlemek i\xe7in gerekli oldu\u011funu savunuyor. Yorumlarda Steam'in PC video oyun da\u011f\u0131t\u0131m\u0131ndaki tekelinin eti\u011fi tart\u0131\u015f\u0131l\u0131rken, tekellere duyulan ihtiya\xe7 ve hile kar\u015f\u0131t\u0131 yaz\u0131l\u0131mlar\u0131n etkinli\u011fi konusunda farkl\u0131 g\xf6r\xfc\u015fler dile getiriliyor."]}),"\n",(0,n.jsx)(e.h2,{id:"plastik-ambalajl\u0131-bir-hindili-sandvi\xe7-neden-new-york-havaalan\u0131nda-15-dolar",children:"Plastik ambalajl\u0131 bir hindili sandvi\xe7 neden New York havaalan\u0131nda 15 dolar?"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://hellgatenyc.com/why-is-airport-turkey-sandwich-expensive",children:"Orijinal"}),".\nYOK."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35580847",children:"Discussion Service"}),".\nDiscussion Service kullan\u0131c\u0131lar\u0131 NYC havalimanlar\u0131nda plastik ambalajl\u0131 bir hindili sandvi\xe7in 15 dolar olmas\u0131n\u0131n nedenlerini tart\u0131\u015f\u0131yor; havalimanlar\u0131ndaki s\u0131n\u0131rl\u0131 rekabet ve yiyecek-i\xe7ecek sat\u0131c\u0131lar\u0131n\u0131n kar\u015f\u0131la\u015ft\u0131r\u0131labilir olmamas\u0131 adil fiyatland\u0131rmay\u0131 imkans\u0131z k\u0131l\u0131yor. Kullan\u0131c\u0131lar bunun yerine yolcular\u0131n kendi yemeklerini getirmelerini \xf6neriyor."]}),"\n",(0,n.jsx)(e.h2,{id:"lofi-hava-trafik-kontrol\xfc---lax",children:"Lofi hava trafik kontrol\xfc - LAX"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.lofiatc.com/?icao=KLAX",children:"Orijinal"}),".\nG\xf6nderi, KLAX'taki Los Angeles Kulesi'nin (Kuzey) 133.900 olan frekans\u0131n\u0131 payla\u015fmaktad\u0131r. G\xf6nderide Glimlip x Yasper taraf\u0131ndan haz\u0131rlanan bir m\xfczik videosu yer al\u0131yor ve geri bildirim ya da ba\u011f\u0131\u015f i\xe7in bir se\xe7enek sunuluyor."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35583228",children:"Discussion Service"}),".\nHacker News kullan\u0131c\u0131lar\u0131, ortam m\xfczi\u011fi ile hava trafik kontrol ileti\u015fimini rahatlat\u0131c\u0131 bir \u015fekilde birle\u015ftiren yeni bir web uygulamas\u0131 olan lofiatc.com'u tart\u0131\u015f\u0131yor ve ilgi uyand\u0131r\u0131yor; baz\u0131 kullan\u0131c\u0131lar ek \xf6zellikler ve radyo sohbetleri talep ediyor. Kullan\u0131c\u0131lar ayr\u0131ca, konsantrasyon i\xe7in en iyi ortam m\xfczi\u011fi t\xfcr\xfc konusunda net bir fikir birli\u011fi olmamas\u0131na ra\u011fmen, SomaFM ve mynoise.net \xf6nerileri ve uygun bir alternatif olarak black metal \xf6neren birka\xe7 kullan\u0131c\u0131 ile \xe7al\u0131\u015f\u0131rken ortam m\xfczi\u011fi tercihlerini payla\u015f\u0131yorlar."]}),"\n",(0,n.jsx)(e.h2,{id:"transformat\xf6r-modelleri-nelerdir-ve-nas\u0131l-\xe7al\u0131\u015f\u0131rlar",children:"Transformat\xf6r modelleri nelerdir ve nas\u0131l \xe7al\u0131\u015f\u0131rlar?"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://txt.cohere.ai/what-are-transformer-models/",children:"Orijinal"}),".\nD\xf6n\xfc\u015ft\xfcr\xfcc\xfc modeller makine \xf6\u011freniminde yeni bir geli\u015fmedir ve ba\u011flam\u0131 izleyerek tutarl\u0131 metin \xfcretme konusunda ustad\u0131r. Diller aras\u0131nda \xe7eviri yapma ve sorular\u0131 yan\u0131tlama gibi \xe7e\u015fitli g\xf6revleri yerine getirme yetene\u011fine sahip olan d\xf6n\xfc\u015ft\xfcr\xfcc\xfcler, tokenizasyon, g\xf6mme, konumsal kodlama, d\xf6n\xfc\u015ft\xfcr\xfcc\xfc bloklar ve softmax dahil olmak \xfczere \xe7e\u015fitli bile\u015fenlerden olu\u015fur. En karma\u015f\u0131k d\xf6n\xfc\u015ft\xfcr\xfcc\xfc blo\u011fu, vekt\xf6rleri de\u011fi\u015ftirmek ve daha fazla ba\u011flam sa\u011flamak i\xe7in kullan\u0131lan \xe7ok kafal\u0131 dikkat ile dikkat ve ileri besleme bile\u015fenlerini kullan\u0131r. E\u011fitim sonras\u0131, transformat\xf6rlere belirli g\xf6revleri yerine getirmeyi \xf6\u011fretir ve ba\u011flam\u0131 yakalama yetenekleri ba\u015far\u0131lar\u0131na yol a\xe7m\u0131\u015ft\u0131r."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35576918",children:"Discussion Service"}),".\nKullan\u0131c\u0131lar transformat\xf6r modelleri hakk\u0131nda tart\u0131\u015fmalara girmekte, bunlar\u0131n etkinli\u011fini ve tan\u0131t\u0131m i\xe7eri\u011finin kapsaml\u0131l\u0131\u011f\u0131n\u0131 sorgulamaktad\u0131r. Tokenle\u015ftirme i\xe7in alternatif y\xf6ntemlerden bahsediliyor ve daha fazla bilgi edinmek i\xe7in kurslar, videolar ve makaleler de dahil olmak \xfczere kaynaklar \xf6neriliyor. Yapay zekada basit modeller taraf\u0131ndan g\xf6sterilen ortaya \xe7\u0131kan davran\u0131\u015f ve hesaplama detaylar\u0131 ile \xfcst d\xfczey davran\u0131\u015f aras\u0131ndaki ba\u011flant\u0131 ara\u015ft\u0131r\u0131lmakta ve mekanistik yorumlanabilirlik ad\u0131 verilen aktif bir \xe7al\u0131\u015fma alan\u0131 vurgulanmaktad\u0131r."]}),"\n",(0,n.jsx)(e.h2,{id:"webgpu-temelleri",children:"WebGPU Temelleri"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://webgpufundamentals.org/",children:"Orijinal"}),".\nBu yaz\u0131, veri belle\u011fi d\xfczeni, 3D matematik ve WebGL'den WebGPU dahil olmak \xfczere WebGPU'nun temellerini \xf6\u011frenmek i\xe7in bir dizi makale sunmaktad\u0131r. Yaz\u0131da ayr\u0131ca daha fazla \xe7al\u0131\u015fma i\xe7in kaynaklar ve referanslar\u0131n yan\u0131 s\u0131ra katk\u0131 f\u0131rsatlar\u0131 da yer almaktad\u0131r. Katk\u0131lar\u0131 i\xe7in jrprice'a te\u015fekk\xfcr ederiz."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35579334",children:"Discussion Service"}),".\nWebGPU Fundamentals, web taray\u0131c\u0131lar\u0131nda grafikler i\xe7in WebGL'nin halefi olarak Hacker News'de dikkat \xe7ekiyor. Kullan\u0131c\u0131lar sim\xfclasyon, derin \xf6\u011frenme ve taray\u0131c\u0131 \xf6zelliklerinin artmas\u0131yla ilgili endi\u015feler i\xe7in potansiyel uygulamalar\u0131 tart\u0131\u015f\u0131yor. Yorumlar ayr\u0131ca web tabanl\u0131 MIDI s\u0131ralay\u0131c\u0131lar, deneysel enstr\xfcmanlar ve \xfcr\xfcn yaz\u0131l\u0131m\u0131 g\xfcncellemeleri i\xe7in WebUSB'ye de de\u011finiyor. Baz\u0131lar\u0131 web tabanl\u0131 ara\xe7lar\u0131n avantajlar\u0131n\u0131 savunurken, di\u011ferleri g\xfcvenlik riskleri ve uyumluluk sorunlar\u0131 konusundaki endi\u015felerini dile getiriyor. WebGPU'nun y\xfcksek seviyeli ya da yeni ba\u015flayanlar i\xe7in eri\u015filebilir olmas\u0131 de\u011fil, uzman kullan\u0131c\u0131lar i\xe7in d\xfc\u015f\xfck seviyeli bir GPU API'si olmas\u0131 ama\xe7lanm\u0131\u015ft\u0131r."]}),"\n",(0,n.jsx)(e.h2,{id:"google-ceosu-bu-grubun-ayar\u0131n\u0131-ge\xe7mi\u015f-kapal\u0131-olarak-de\u011fi\u015ftirebilir-miyiz-pdf",children:'Google CEO\'su: "bu grubun ayar\u0131n\u0131 ge\xe7mi\u015f kapal\u0131 olarak de\u011fi\u015ftirebilir miyiz" [pdf]'}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://ia601707.us.archive.org/28/items/gov.uscourts.cand.364454/gov.uscourts.cand.364454.385.0.pdf",children:"Orijinal"}),".\nHacker News, WebGL'in halefi olan WebGPU Fundamentals'\u0131 istemci taraf\u0131 derin \xf6\u011frenme ve taray\u0131c\u0131 sim\xfclasyonlar\u0131ndaki potansiyeli nedeniyle tart\u0131\u015f\u0131yor. Konu\u015fmalar ayr\u0131ca taray\u0131c\u0131 \xf6zelliklerinin artmas\u0131, potansiyel kullan\u0131\u015fl\u0131l\u0131\u011f\u0131 ve rahatl\u0131\u011f\u0131 ile taray\u0131c\u0131lar\u0131n uygulama veya g\xf6r\xfcnt\xfcleyici olarak kapsam\u0131 konular\u0131na da de\u011finiyor. Ayr\u0131ca, kullan\u0131c\u0131lar WebGPU kullanarak metin olu\u015fturman\u0131n yollar\u0131n\u0131, yapay zeka projeleriyle uyumlulu\u011funu ve WebGPU ekipleri aras\u0131nda devam eden i\u015fbirli\u011fini tart\u0131\u015f\u0131yor."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35585174",children:"Discussion Service"}),".\nGoogle CEO'su Sundar Pichai, potansiyel yasal sonu\xe7lara ve FRCP 37(e)'nin ihlaline ra\u011fmen Google Chat grup ayarlar\u0131nda \"ge\xe7mi\u015fi kapatma\" y\xf6n\xfcnde bir de\u011fi\u015fiklik talep etmekle su\xe7lan\u0131yor. Discussion Service kullan\u0131c\u0131lar\u0131, mesajlar\u0131 silen di\u011fer elektronik ileti\u015fim \xf6rnekleri ile ke\u015ffedilebilir kay\u0131tlar\u0131 koruman\u0131n \xf6nemini ve otomatik silme uygulamalar\u0131n\u0131n yasall\u0131\u011f\u0131na ili\u015fkin endi\u015feleri tart\u0131\u015f\u0131yor. Ayr\u0131ca, veri saklama, h\xfck\xfcmet d\xfczenlemeleri ve d\xfcnya \xe7ap\u0131ndaki tekellerle ilgili tart\u0131\u015fmalar payla\u015f\u0131l\u0131rken, Google'\u0131n Android i\u015fi ve rekabet eksikli\u011fi ile ilgili endi\u015feler ortaya \xe7\u0131k\u0131yor."]}),"\n",(0,n.jsx)(e.h2,{id:"surviving-burnout-2015",children:"Surviving Burnout (2015)"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://lifeofaudrey.com/essays/surviving_burnout.html",children:"Orijinal"}),".\nTeknoloji sekt\xf6r\xfcndeki t\xfckenmi\u015flik, sorumluluk, yetki ve kaynaklar\u0131n yanl\u0131\u015f hizalanmas\u0131ndan kaynaklanmaktad\u0131r. Yazar\u0131n t\xfckenmi\u015flik deneyimi onu i\u015finden ayr\u0131lmaya ve bir iyile\u015fme s\xfcrecine girmeye itmi\u015f, bu da kendi i\u015fini kurmas\u0131na yol a\xe7m\u0131\u015ft\u0131r. T\xfckenmi\u015flik, yap\u0131sal \xe7\xf6z\xfcmler gerektiren yap\u0131sal bir sorundur ve etkilenenler i\xe7in iyile\u015fme deste\u011fi ve fonlar gereklidir."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35577285",children:"Discussion Service"}),".\nHacker News'de yer alan bir makalede, t\xfckenmi\u015flikten ka\xe7\u0131nmak ve zihinsel ve fiziksel sa\u011fl\u0131\u011f\u0131 korumak i\xe7in denge kurman\u0131n \xf6nemi tart\u0131\u015f\u0131l\u0131rken, kullan\u0131c\u0131lar ki\u015fisel deneyimlerini payla\u015f\u0131yor ve tavsiyelerde bulunuyor. Baz\u0131 Discussion Service kullan\u0131c\u0131lar\u0131 depresyon ve t\xfckenmi\u015flik aras\u0131ndaki farklar\u0131 vurgularken, di\u011ferleri t\xfckenmi\u015fli\u011fe neden olan i\u015fyerleriyle ba\u015fa \xe7\u0131kmak veya potansiyel bir \xe7\xf6z\xfcm olarak bir i\u015f kurmak i\xe7in ipu\xe7lar\u0131 sunuyor. Baz\u0131 okuyucular da \xe7al\u0131\u015fanlar\u0131n t\xfckenmi\u015fli\u011fiyle m\xfccadele etmek i\xe7in bir ya\u015fam tarz\u0131 ko\xe7u ya da terapiste sahip olman\u0131n etkinli\u011fini tart\u0131\u015f\u0131yor. Sonu\xe7 olarak, temel \xe7\u0131kar\u0131m, i\u015fi \xf6nemsemenin \xf6nemli oldu\u011fu, ancak ki\u015finin refah\u0131 pahas\u0131na olmad\u0131\u011f\u0131d\u0131r."]}),"\n",(0,n.jsx)(e.h2,{id:"d\xfc\u015f\xfck-kodlu-yaz\u0131l\u0131m-geli\u015ftirme-bir-yaland\u0131r",children:"D\xfc\u015f\xfck Kodlu Yaz\u0131l\u0131m Geli\u015ftirme Bir Yaland\u0131r"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://jaylittle.com/post/view/2023/4/low-code-software-development-is-a-lie",children:"Orijinal"}),'.\nDeneyimli bir yaz\u0131l\u0131m geli\u015ftiricisi, kodlama dilleri ve ara\xe7lar\u0131n\u0131n hatas\u0131ndan ziyade, m\xfc\u015fterilerin ve geli\u015ftiricilerin \xe7\xf6zmek istedikleri sorunlar\u0131n temel nedenlerini anlamamalar\u0131 nedeniyle yaz\u0131l\u0131m olu\u015fturman\u0131n zor oldu\u011funu savunuyor. Yazar, OutSystems gibi "d\xfc\u015f\xfck kodlu" ara\xe7lar fikrini ele\u015ftirerek, bu ara\xe7lar\u0131n do\u011fas\u0131nda var olan karma\u015f\u0131kl\u0131\u011f\u0131 ortadan kald\u0131rmad\u0131\u011f\u0131n\u0131 ve k\xf6t\xfc d\xfc\u015f\xfcn\xfclm\xfc\u015f yaz\u0131l\u0131m sistemlerine yol a\xe7abilece\u011fini, ayr\u0131ca pahal\u0131 olduklar\u0131n\u0131 ve sat\u0131c\u0131 kilitlenmesini i\xe7erdiklerini belirtmektedir. Bir \xe7\xf6z\xfcm\xfc do\u011fru bir \u015fekilde tasarlamak yaz\u0131l\u0131m geli\u015ftirme s\xfcrecinin en zor k\u0131sm\u0131d\u0131r ve hi\xe7bir ara\xe7 gerekli d\xfc\u015f\xfcnme, tart\u0131\u015fma ve planlaman\u0131n yerini alamaz.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35578240",children:"Discussion Service"}),".\nD\xfc\u015f\xfck kodlu yaz\u0131l\u0131m geli\u015ftirme daha basit problemler i\xe7in faydal\u0131d\u0131r ancak karma\u015f\u0131k problemler i\xe7in uygun de\u011fildir ve geli\u015ftiricilerin yerini tamamen almamal\u0131d\u0131r. Discussion Service yorumlar\u0131, d\xfc\u015f\xfck kodlu platformlar\u0131n, sat\u0131c\u0131 kilitlenmesine yol a\xe7abilecek zay\u0131f test edilebilirlik, s\xfcr\xfcm olu\u015fturma ve hata ay\u0131klama ara\xe7lar\u0131 da dahil olmak \xfczere s\u0131n\u0131rlamalar\u0131n\u0131 ve \xf6d\xfcnle\u015fimlerini tart\u0131\u015fmaktad\u0131r. Baz\u0131 uzmanlar d\xfc\u015f\xfck kodlu ara\xe7lar\u0131n prototip olu\u015fturma ve belirli uygulamalar i\xe7in de\u011ferli olabilece\u011fini \xf6ne s\xfcrerken, di\u011ferleri bunlara a\u015f\u0131r\u0131 g\xfcvenilmemesi konusunda uyar\u0131da bulunmakta ve uygun ara\xe7lar\u0131n dikkatle se\xe7ilmesini tavsiye etmektedir. Low-code'un \xe7e\u015fitli kullan\u0131m alanlar\u0131 olsa da, tan\u0131m\u0131 bulan\u0131k ve potansiyel olarak yan\u0131lt\u0131c\u0131d\u0131r; Excel ve shader grafikleri buna \xf6rnek olarak verilebilir."]}),"\n",(0,n.jsx)(e.h2,{id:"googleda-d\xfczeltmek-istemedikleri-uzaktan-kod-\xe7al\u0131\u015ft\u0131rma-g\xfcvenlik-a\xe7\u0131\u011f\u0131",children:"Google'da d\xfczeltmek istemedikleri uzaktan kod \xe7al\u0131\u015ft\u0131rma g\xfcvenlik a\xe7\u0131\u011f\u0131"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://giraffesecurity.dev/posts/google-remote-code-execution/",children:"Orijinal"}),".\nBir g\xfcvenlik ara\u015ft\u0131rmac\u0131s\u0131, Google'da Python'un y\xf6netim sistemindeki ba\u011f\u0131ml\u0131l\u0131k kar\u0131\u015f\u0131kl\u0131\u011f\u0131ndan kaynaklanan ve 50'den fazla Google \xe7al\u0131\u015fan\u0131n\u0131n bilgisayarlar\u0131nda keyfi kod \xe7al\u0131\u015ft\u0131rmalar\u0131na izin veren bir g\xfcvenlik a\xe7\u0131\u011f\u0131 buldu. Google ba\u015flang\u0131\xe7ta bunu ciddi olarak s\u0131n\u0131fland\u0131rd\u0131 ancak daha sonra bunu ama\xe7lanan davran\u0131\u015f olarak de\u011fi\u015ftirdi. Ara\u015ft\u0131rmac\u0131, Google \xe7al\u0131\u015fanlar\u0131ndan her g\xfcn indirme ald\u0131klar\u0131 i\xe7in g\xfcvenlik a\xe7\u0131\u011f\u0131n\u0131n istismar edilebilece\u011finden korkuyor ve Google'\u0131n sorunu anlamad\u0131\u011f\u0131ndan ya da d\xfczeltmeyi umursamad\u0131\u011f\u0131ndan \u015f\xfcpheleniyor."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35581532",children:"Discussion Service"}),".\nGoogle'\u0131n yaz\u0131l\u0131m\u0131nda bulunan bir Uzaktan Kod Y\xfcr\xfctme (RCE) a\xe7\u0131\u011f\u0131n\u0131n d\xfczeltilmedi\u011fi bildirilirken, baz\u0131 kullan\u0131c\u0131lar Java'n\u0131n paket y\xf6netim sisteminin Rust'\u0131n sisteminden daha g\xfcvenli bir paket y\xfckleme y\xf6ntemine sahip oldu\u011funa i\u015faret ederken, di\u011ferleri `pip install --extra-index-url'\xfcn kullan\u0131c\u0131ya \xf6zel kay\u0131tlar\u0131 yok sayarak \xf6zel kay\u0131tlar\u0131 i\u015fe yaramaz hale getirdi\u011fini \xf6ne s\xfcr\xfcyor. Google, i\xe7eriden gelen tehditlerle m\xfccadele etmek i\xe7in s\u0131f\u0131r g\xfcven g\xfcvenlik \xf6nlemlerine sahiptir, ancak bir APT bu g\xfcvenlik a\xe7\u0131\u011f\u0131n\u0131 ortamda bir yer edinmek i\xe7in kullanabilir. Daha iyi paket y\xf6netimi \xe7\xf6z\xfcmlerine duyulan ihtiya\xe7 ve s\u0131f\u0131r g\xfcvenin bu t\xfcr sald\u0131r\u0131lar\u0131 \xf6nlemedeki rol\xfc de vurgulanmaktad\u0131r."]}),"\n",(0,n.jsx)(e.h2,{id:"rustta-hiperviz\xf6r-geli\u015ftirme",children:"Rust'ta Hiperviz\xf6r Geli\u015ftirme"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://memn0ps.github.io/hypervisor-development-in-rust-part-1/",children:"Orijinal"}),".\nBu makale, Intel VT-x sanalla\u015ft\u0131rma i\xe7in Rust tabanl\u0131 bir ara\u015ft\u0131rma hiperviz\xf6r\xfcn\xfcn geli\u015ftirilmesini a\xe7\u0131klamakta, VMX i\u015flemi i\xe7in Rust kod \xf6rnekleri sunmakta ve sanal CPU'lar i\xe7in bellek b\xf6lgelerini ba\u015flatma s\xfcrecini tart\u0131\u015fmaktad\u0131r. Rust kullanarak sanalla\u015ft\u0131rma alan\u0131ndaki uzmanlar i\xe7in yararl\u0131 bir kaynak olmay\u0131 ama\xe7lamaktad\u0131r. Makale tarafs\u0131zl\u0131\u011f\u0131n\u0131 korumakta ve referanslar ve krediler sa\u011flamaktad\u0131r."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35579876",children:"Discussion Service"}),".\nBir Hacker News kullan\u0131c\u0131s\u0131 CPU sanalla\u015ft\u0131rma hakk\u0131ndaki makaleye yorum yap\u0131yor ve cihaz sanalla\u015ft\u0131rmaya olan ilgisini ifade ediyor, kar\u015f\u0131la\u015f\u0131lan zorluklar\u0131 vurguluyor ve yeni \xe7\xf6z\xfcmler \xf6neriyor. Di\u011fer kullan\u0131c\u0131lar bu alanla ilgilenen Linux kullan\u0131c\u0131lar\u0131 i\xe7in kaynaklar ve alternatifler sunmaktad\u0131r."]})]})}function k(a={}){const{wrapper:e}={...(0,r.R)(),...a.components};return e?(0,n.jsx)(e,{...a,children:(0,n.jsx)(o,{...a})}):o(a)}}}]);